<script lang="ts">import {page}from '$app/state';import {createPipelineSchedule,getPipelineDefinition,listPipelineSchedules,pipelineErrorMessage,updatePipelineSchedule,type NexetlError,type PipelineDefinition,type PipelineSchedule}from '$lib/api/pipelines';import {formatTimestamp}from '$lib/format';import PipelineWorkspaceNav from '$lib/components/PipelineWorkspaceNav.svelte';import PageHeader from '$lib/components/ui/PageHeader.svelte';import Button from '$lib/components/ui/Button.svelte';import Alert from '$lib/components/ui/Alert.svelte';let pipeline=$state<PipelineDefinition|null>(null),items=$state<PipelineSchedule[]>([]),error=$state(''),name=$state('Daily run'),expression=$state('0 2 * * *'),timezone=$state('UTC'),pending=$state(false);$effect(()=>{if(page.params.pipelineDefinitionId)void load(page.params.pipelineDefinitionId)});async function load(id:string){try{[pipeline,{items}]=await Promise.all([getPipelineDefinition(id),listPipelineSchedules(id)])}catch(e){error=pipelineErrorMessage(e as NexetlError)}}async function create(){if(!pipeline)return;pending=true;try{await createPipelineSchedule(pipeline.id,{name,expression,timezone,enabled:true});await load(pipeline.id)}catch(e){error=pipelineErrorMessage(e as NexetlError)}finally{pending=false}}async function toggle(item:PipelineSchedule){if(!pipeline)return;try{await updatePipelineSchedule(pipeline.id,item.id,{enabled:!item.enabled});await load(pipeline.id)}catch(e){error=pipelineErrorMessage(e as NexetlError)}}</script>
<svelte:head><title>Schedules | NEXETL</title></svelte:head>{#if pipeline}<PageHeader title={pipeline.name} description="Timezone-aware recurring execution."></PageHeader><PipelineWorkspaceNav pipelineId={pipeline.id}/>{/if}{#if error}<Alert variant="error">{error}</Alert>{/if}<div class="grid"><section><h2>Schedules</h2>{#each items as item}<article><div><strong>{item.name}</strong><small>{item.expression} · {item.timezone}</small><small>Next: {formatTimestamp(item.nextRunAt)}</small></div><button class:enabled={item.enabled} onclick={()=>toggle(item)}>{item.enabled?'Enabled':'Disabled'}</button></article>{:else}<p>No schedules yet.</p>{/each}</section><form onsubmit={(e)=>{e.preventDefault();void create()}}><h2>Create schedule</h2><label>Name<input bind:value={name} required/></label><label>Cron expression<input bind:value={expression} required/></label><label>Timezone<input bind:value={timezone} required/></label><Button type="submit" loading={pending}>Create schedule</Button><p>Example: <code>0 2 * * *</code> runs daily at 02:00 in the selected timezone.</p></form></div>
<style>.grid{display:grid;grid-template-columns:1fr minmax(18rem,.55fr);gap:1rem}.grid>section,form{border:1px solid var(--border-default);border-radius:var(--radius-lg);background:#fff;padding:1rem}h2{margin-top:0;font-size:.9rem}article{display:flex;align-items:center;justify-content:space-between;border-top:1px solid var(--border-subtle);padding:.7rem 0}article small{display:block;margin-top:.15rem;color:var(--text-muted);font-size:.62rem}article button{border:1px solid var(--border-default);border-radius:999px;background:#fff;padding:.3rem .55rem;font-size:.62rem}.enabled{border-color:#a9ddca!important;background:#effaf6!important;color:#176f52}label{display:grid;gap:.3rem;margin-bottom:.7rem;color:var(--text-secondary);font-size:.68rem;font-weight:650}input{height:2.25rem;border:1px solid var(--border-default);border-radius:6px;padding:.5rem}form p{color:var(--text-muted);font-size:.62rem}@media(max-width:750px){.grid{grid-template-columns:1fr}}</style>
